Actionscript.script:
function 追踪生成红水晶(x, y)
{
	兵种 = "敌人-红水晶";
	等级 = _parent.等级;
	名字 = "水晶";
	是否为敌人 = _parent.是否为敌人;
	身高 = 175;
	_parent.水晶计数 = _parent.水晶计数 % 20 + 1;
	var 产生源名 = this._name;
	if (_parent._arenaCalibrationUnit === true) 产生源名 = _parent._name;
	僵尸型敌人newname = 产生源名 + 兵种 + _parent.水晶计数;
	_root.加载游戏世界人物(兵种,僵尸型敌人newname,_root.gameworld.getNextHighestDepth(),{_x:x, _y:y, 等级:this.等级, 名字:this.名字, 是否为敌人:this.是否为敌人, 身高:this.身高, 长枪:this.长枪, 手枪:this.手枪, 手枪2:this.手枪2, 刀:this.刀, 手雷:this.手雷, 产生源:产生源名});
}

连续释放次数 = 0;
function 攻击时移动(慢速度, 快速度)
{
	if (_parent.方向 == "右")
	{
		_parent.移动("右",慢速度);
	}
	else if (_parent.方向 == "左")
	{
		_parent.移动("左",慢速度);
	}
}
function 攻击时四向移动(上, 下, 左, 右)
{
	if (上 != 0)
	{
		_parent.移动("上",上);
	}
	else if (下 != 0)
	{
		_parent.移动("下",下);
	}
	if (左 != 0)
	{
		_parent.方向改变("左");
		_parent.移动("左",左);
	}
	else if (右 != 0)
	{
		_parent.方向改变("右");
		_parent.移动("右",右);
	}
}
gotoAndPlay(_parent.近战招式);

/*连续释放次数 += 1;
if (连续释放次数 < 5 and _parent.hp * 连续释放次数 < _parent.hp满血值)
{
	gotoAndPlay("a0_re");
}
算了有点蠢，弃用了
*/

_parent.水晶计数 = _parent.水晶计数 % 20 + 1;
var 兵种 = "敌人-水晶球";
var 僵尸型敌人newname = this._name + 兵种 + _parent.水晶计数;

_root.加载游戏世界人物(兵种,僵尸型敌人newname,_root.gameworld.getNextHighestDepth(),
	{
		_x:_root.gameworld[_parent.攻击目标]._x, 
		_y:_root.gameworld[_parent.攻击目标].Z轴坐标, 
		等级:this._parent.等级, 
		名字:"水晶球", 
		是否为敌人:_parent.是否为敌人, 
		身高:175, 
		产生源:_parent._name,
		攻击目标:_parent.攻击目标
	}
);

if (_parent.hp * 1.5 < _parent.hp满血值)
{
	追踪生成红水晶(_root.gameworld[_parent.攻击目标]._x,_root.gameworld[_parent.攻击目标].Z轴坐标);
}

if (_parent.hp * 3 < _parent.hp满血值)
{
	追踪生成红水晶(_root.gameworld[_parent.攻击目标]._x,_root.gameworld[_parent.攻击目标].Z轴坐标);
}

targetx = _root.gameworld[_parent.攻击目标]._x;
targety = _root.gameworld[_parent.攻击目标].Z轴坐标;
distance = 90;
if (_root.gameworld[_parent.攻击目标].方向 == "左")
{
	distance = -distance;
}

追踪生成红水晶(targetx + distance,targety - 25);
追踪生成红水晶(targetx + distance,targety + 25);

function 光束攻击(倍率, 攻击area)
{
	//var 子弹 = _root.子弹属性初始化(this.攻击点);
	var 子弹 = _root.子弹属性初始化(攻击area);
	子弹.声音 = "";
	子弹.霰弹值 = 1;
	子弹.子弹散射度 = 0;
	子弹.子弹种类 = "透明子弹";
	子弹.子弹威力 = _parent.空手攻击力 * 倍率;
	子弹.子弹速度 = 0;
	子弹.击中地图效果 = "";
	子弹.Z轴攻击范围 = 50;
	子弹.击倒率 = 10;
	子弹.击中后子弹的效果 = "空手攻击火花";
	子弹.区域定位area = 攻击area;
	子弹.伤害类型 = "魔法";

	_root.子弹区域shoot传递(子弹);
}

function 下砸攻击(倍率)
{
	var 子弹 = _root.子弹属性初始化(this.攻击点);
	子弹.声音 = "";
	子弹.霰弹值 = 1;
	子弹.子弹散射度 = 0;
	子弹.子弹种类 = "近战子弹";
	子弹.子弹威力 = _parent.空手攻击力 * 倍率;
	子弹.子弹速度 = 0;
	子弹.击中地图效果 = "";
	子弹.Z轴攻击范围 = 50;
	子弹.击倒率 = 1;
	子弹.击中后子弹的效果 = "空手攻击火花";
	子弹.区域定位area = this.攻击点;

	_root.子弹区域shoot传递(子弹);
}

//本帧是锁定敌人位置的帧，建议比位移元件早一些。已启用Z轴追踪，所以应尽可能提前于位移元件用于反应。

//你需要改的值，追踪持续帧是从挂载ef的位移元件的第二帧到预计实际到达敌人位置时的总帧数。
速度上限 = _parent.行走X速度 * 3;
速度下限 = _parent.行走X速度 * 1;
追踪持续帧 = 10;

//自动计算的值
敌方目标 = _root.gameworld[_parent.攻击目标];
上速度 = 0;
下速度 = 0;
左速度 = 0;
右速度 = 0;
距离X = _parent._x - 敌方目标._x;
速度X = Math.min(Math.max(距离X / 追踪持续帧, -速度上限), 速度上限);

if (速度X >= 0)
{
	速度X = Math.max(速度X, 速度下限);
	左速度 = 速度X;
}
else
{
	速度X = Math.min(速度X, -速度下限);
	右速度 = -速度X;
}
// 给予Z轴位移能力，启用以下代码，需谨慎给予，且应该比位移元件提前更多帧。
距离Z = _parent.Z轴坐标 - 敌方目标.Z轴坐标;
速度Z = 速度X * 距离Z / 距离X;
if (速度Z >= 0)
{
	上速度 = Math.min(速度Z, 速度上限 * 1);
}
else
{
	下速度 = Math.min(-速度Z, 速度上限 * 1);
}

//本帧是锁定敌人位置的帧，建议比位移元件早一些。已启用Z轴追踪，所以应尽可能提前于位移元件用于反应。

//你需要改的值，追踪持续帧是从挂载ef的位移元件的第二帧到预计实际到达敌人位置时的总帧数。
速度上限 = _parent.行走X速度 * 6;
速度下限 = _parent.行走X速度 * 1;
追踪持续帧 = 5;

//自动计算的值
敌方目标 = _root.gameworld[_parent.攻击目标];
上速度 = 0;
下速度 = 0;
左速度 = 0;
右速度 = 0;
距离X = _parent._x - 敌方目标._x;
速度X = Math.min(Math.max(距离X / 追踪持续帧, -速度上限), 速度上限);

if (速度X >= 0)
{
	速度X = Math.max(速度X, 速度下限);
	左速度 = 速度X;
}
else
{
	速度X = Math.min(速度X, -速度下限);
	右速度 = -速度X;
}
// 给予Z轴位移能力，启用以下代码，需谨慎给予，且应该比位移元件提前更多帧。
距离Z = _parent.Z轴坐标 - 敌方目标.Z轴坐标;
速度Z = 速度X * 距离Z / 距离X;
if (速度Z >= 0)
{
	上速度 = Math.min(速度Z, 速度上限 * 1);
}
else
{
	下速度 = Math.min(-速度Z, 速度上限 * 1);
}

//以下为带追踪的位移代码。如需启用Z轴追踪，则在"追踪代码"图层启用相关代码
onClipEvent(enterFrame){
   _parent.攻击时四向移动(_parent.上速度, _parent.下速度, _parent.左速度, _parent.右速度);
}

//以下为带追踪的位移代码。如需启用Z轴追踪，则在"追踪代码"图层启用相关代码
onClipEvent(enterFrame){
   _parent.攻击时四向移动(_parent.上速度, _parent.下速度, _parent.左速度, _parent.右速度);
}

onClipEvent(load){
   if(_root.是否阴影 == true)
   {
      this._visible = 1;
   }
   else
   {
      this._visible = 0;
   }
}
